#[derive(Clone, Copy, PartialEq)]
pub enum InternalStitchCommand {
    MoveCurr(Highlight),
    MoveNext(Highlight),
    NextRow(Highlight, Highlight),
}

fn nearest_stitch_size(relative_size: f32) -> f32 {
    match relative_size {
        0.0..1.25 => 1.0,
        1.25..1.75 => 1.5,
        1.75..2.5 => 2.0,
        2.5.. => 3.0,
        v => panic!("Incorrect value given to nearest_stitch_size: {v}")
    }
}


/// This panics if a == b.
/// 
/// This returns a result such that:
/// a*lambda + b*(1-lambda) is the closest
/// point to p that lies on the LINE ab.
// This function was partially AI generated
fn calc_lambda(p: PVec3, a: PVec3, b: PVec3) -> f32 {
    let v = a - b;
    (p - b).dot(v) / v.dot(v)
}

/// This returns a result such that:
/// a*lambda + b*(1-lambda) is the closest
/// point to p that lies on the SEGMENT ab.
fn calc_clamped_lambda(p: PVec3, a: PVec3, b: PVec3) -> f32 {
    calc_lambda(p, a, b).clamp(0.0, 1.0)
}

/// This returns a result such that:
/// the result is the closest point to p that lies on the SEGMENT ab.
fn calc_nearest_point(p: PVec3, a: PVec3, b: PVec3) -> PVec3 {
    if a == b {
        a
    } else {
        let lambda = calc_clamped_lambda(p, a, b);
        a * lambda + b * (1.0 - lambda)
    }
}

// This function was AI generated.
fn intersect(n: PVec3, a: PVec3, b: PVec3, c: PVec3, d: PVec3) -> PVec3 {
    let r = b - a;
    let t = (c - a).cross(d - c).dot(n) / r.cross(d - c).dot(n);
    a + r * t
}

#[derive(Clone, Copy, PartialEq)]
pub struct Highlight(pub HighlightPoint, pub HighlightPoint);

impl Highlight {
    pub fn null() -> Self {
        let null = HighlightPoint { pos: PVec3::splat(0.0), isoline_index: 0 };
        Self(null, null)
    }
}

#[derive(Clone, Copy, PartialEq)]
pub struct HighlightPoint {
    pub pos: PVec3,
    pub isoline_index: usize
}

impl From<StitchPoint> for HighlightPoint {
    fn from(value: StitchPoint) -> Self {
        Self {
            pos: value.pos,
            isoline_index: value.isoline_index
        }
    }
}

